<script setup lang="ts">import {onMounted,ref} from 'vue';import http from '../api/http';import PublicState from './PublicState.vue';const loading=ref(true),error=ref(''),items=ref<any[]>([]);onMounted(async()=>{try{items.value=(await http.get('/public/campuses')).data.data;}catch(e:any){error.value=e.message??'加载失败';}finally{loading.value=false;}});</script><template><section class="page"><h1>院区导航</h1><PublicState :loading="loading" :error="error" :empty="!items.length"><article v-for="item in items" :key="item.id" class="detail"><h2>{{item.name}}</h2><p>{{item.address}}</p><p>{{item.transportation}}</p><p>{{item.parkingInfo}}</p><p>{{item.businessHours}}</p></article></PublicState></section></template>
